"""Campaign-approved context and proposed commitments for fictional Caprica."""

SLOGAN = "Freedom to Build. Confidence in Tomorrow."
PROMISES = [
    "The freedom to get ahead",
    "The confidence to plan your future",
    "The power to shape your own life",
]

# Every numerical forward commitment below is a proposal, not a claimed result.
# The supplied current fiscal outturn is gross debt of 69% of GDP in 2068.
PAGES = [
    dict(id="housing", part=0, title="A home to build your life around.",
         intro="A reliable rent, a first set of keys or a smaller home near family should be within reach. More homes, connected to jobs and services, are the foundation of independence.",
         entries=[
             ("Build 50% more homes by 2072", "Raise annual completions by 50% against the independently verified 2068 total. Publish that baseline within 100 days, with monthly regional starts, completions and costs. National and regional growth compacts will identify serviced land, builders and workforce capacity before setting local delivery schedules."),
             ("Give planning a clock", "Decide complete applications in designated growth zones within 120 days, with a 60-day route for compliant, pre-approved infill designs. Missed deadlines trigger a fee refund and independent appeal. Safety, flood, habitat and infrastructure requirements remain enforceable, with reasons for every refusal published."),
             ("Put homes where life happens", "Allow well-designed apartments and mixed-use development within 800 meters of rapid transit and in established town centers. Release suitable public land through competitive tenders with construction deadlines. Pattern books and interoperable modular standards will cut repeat design costs without lowering quality."),
             ("Connect homes before occupation", "Use ten-year growth compacts and a revolving Infrastructure Capacity Fund for water, power, schools and transport. Published development levies and land-value capture repay eligible advances. Borrowing requires an independently tested capital case, including maintenance and the risk that expected land receipts fall short."),
             ("Make renting secure", "Introduce clear long-term contracts, portable deposits and enforceable standards for warmth, safety and repairs. A specialist tribunal will target resolution within 30 days. Publish local rent and vacancy data; reform supply rather than freeze rents in ways that deter new homes."),
             ("Make ownership an attainable choice", "Offer portable housing savings accounts and tightly capped shared-equity places for eligible working households in additional new homes. Publish income limits, resale rules and subsidy costs. Assistance must add supply, avoid bidding up scarce existing homes and pass the same fiscal tests as other spending."),
         ], delivery="By 2069: growth compacts and planning clocks. By 2072: 50% more annual completions than in 2068."),
    dict(id="tax", part=0, title="Let work take you further.",
         intro="The benefit of a pay raise should reach the household that earned it. A predictable tax system also lets a shop owner hire, a parent return to work and a family save with confidence.",
         entries=[
             ("Keep the negative income tax", "Retain the 20% earnings credit on the first 20,000 aurums of the reference income band, paid through payroll with annual reconciliation. That is up to 4,000 aurums before other credits and statutory indexation. Publish the indexed schedule each budget and offer a simple route for irregular earners."),
             ("End silent tax increases", "Continue annual CPI indexation of the reference 20,000, 40,000, 60,000 and 80,000 aurum thresholds. Any suspension must be openly legislated and costed. Treasury will publish the combined tax and benefit withdrawal rate at each income step so higher earnings do not produce hidden losses."),
             ("Make childcare help usable", "Keep the childcare credit refundable and offer monthly payment. Apply equal rules to married, unmarried and single parents. Accredited centers, family day care and extended-hour providers may participate, with common safety standards, published fees and checks that the credit reaches families."),
             ("Give enterprise predictable rates", "Hold the established 20% VAT, 30% land-value tax and 5%, 8% and 10% corporate-rate structure in the first budget. Publish a five-year roadmap and explain tax bases and eligibility. Later changes require independent fiscal assessment, distributional analysis and at least 90 days' notice."),
             ("Reward productive investment", "Allow immediate expensing of qualifying machinery, software and clean equipment. Retain the 40% research and human-capital credit for audited additional spending above a published recent baseline. Exclude relabeled routine costs and related-party inflation; evaluate productivity gains and recover improper claims."),
             ("Let more people own a stake", "Defer employee-share tax until a genuine opportunity to sell, with anti-avoidance rules for disguised salary. Permit capital-gains deferral for qualifying reinvestment in Caprican startups. Cap reliefs, publish their cost and review whether they widen ownership rather than shelter established wealth."),
         ], delivery="First budget: indexed tax schedules, monthly-credit option and a public tax-and-benefit calculator."),
    dict(id="enterprise", part=0, title="Make room for the next good idea.",
         intro="Caprica's next employer may be a family business adding a second shop or a researcher opening a laboratory. Neither should need political connections to get started.",
         entries=[
             ("A 24-hour business start", "Build on the existing digital business gateway with a one-day incorporation service for complete standard applications. Reuse verified information with consent, combine routine filings and provide a staffed alternative. Regulated activities still require their safety approvals; applicants will see one status tracker and a named contact."),
             ("Pay small suppliers on time", "Require public bodies to pay undisputed small-business invoices within 20 working days, with automatic interest and published compliance. Contracts will identify responsibility for disputed invoices. Large prime contractors on public projects must pass equivalent terms through to subcontractors."),
             ("Measure burdens, not paperwork counts", "Apply a one-in, two-out rule to comparable material compliance costs, with an independently checked calculation. Parliament may approve justified exceptions for safety or other public interests. Review major economic regulations every seven years, retaining protections whose benefits exceed their costs."),
             ("Open public contracts", "Break suitable contracts into lots smaller firms can bid for; use proportionate insurance and turnover requirements. Publish beneficial ownership, award reasons and contract changes. Innovation challenges will buy a measurable solution through fair competition, with transparent testing and no permanent preference for favored firms."),
             ("Make competition work", "Give the Competition Authority effective market investigations and interim remedies, subject to appeal. Scrutinize anti-competitive state preferences, exclusionary platforms and concentrated essential markets. Easier switching, transparent charges and data portability will give consumers practical choices and efficient challengers a fair entry route."),
             ("Test new technology responsibly", "Offer time-limited supervised trials for maritime, financial, health and clean-energy technology, with defined participant protections and liability. Publish evaluation criteria before admission. A successful pilot must earn ordinary regulatory approval; a failed pilot must close without leaving the public with hidden liabilities."),
         ], delivery="By 2069: the incorporation service and prompt-payment duty. Annual reporting on entry, competition and contract access."),
    dict(id="work", part=0, title="A route forward at every age.",
         intro="The first job matters. So does the chance to change careers at forty, return after caring or learn a new skill without starting life over. Opportunity should stay open.",
         entries=[
             ("A next step for young people", "After four months outside work or education, every under-25 will receive a named adviser and an apprenticeship, technical training or employment offer within 90 days. Offers must be suitable, paid where work is involved and reachable by transport. Publish sustained outcomes, not just referral counts."),
             ("Skills that belong to the worker", "Create portable accredited training accounts, co-funded by employers and government within a published annual budget. Prioritize shortage skills and workers changing industries. Information on course completion, employment and earnings will help people choose; poor-performing providers will lose access after a fair review."),
             ("Apprenticeships beyond large firms", "Let larger employers direct part of their training levy to accredited supply-chain apprenticeships. Use unspent balances for small-employer places, with shared administration and recognized qualifications. Funding follows verified training and completion rather than the relabeling of existing jobs."),
             ("A fair return to work", "Combine overlapping working-age support with a clear earnings disregard and gradual taper. Protect essential disability and caring support. Work trials will not trigger immediate benefit cancellation; adverse decisions require reasons, human review and appeal. Publish transition rules before changing anyone's entitlement."),
             ("Respect lawful choices at work", "Protect the right to join a union, bargain collectively or individually, and decline membership. Enforce pay, safety and anti-retaliation law through accessible complaints and timely inspections. Predictable contracts and portable benefits should support flexible work without disguising employment as self-employment."),
             ("Remove practical barriers", "Coordinate training schedules with childcare, accessible transport and rehabilitation. Recognize prior learning and relevant experience so mature workers need not repeat basic courses. Job services will have 20 working days to agree a plan with work-ready claimants and explain the support available."),
         ], delivery="By 2070: the 90-day next-step guarantee, with completion and sustained employment reported by region."),
    dict(id="schools", part=0, title="Strong beginnings. Open futures.",
         intro="Families should be able to trust the school down the road. Excellent teaching and clear standards give every child a foundation that wealth or family connections cannot substitute for.",
         entries=[
             ("Start before the first school day", "Offer an early language and development check two years before school, followed by timely support when needed. Early learning will combine structured play, movement, curiosity and language. Share a single assessment across education, health and care with parental consent and clear privacy protections."),
             ("Teach the foundations well", "Protect daily reading, writing and mathematics in primary years, supported by evidence-based materials and low-stakes progress checks. Science, civic knowledge and critical thinking complete the core. National standards set the destination; teachers retain professional judgment about how to get pupils there."),
             ("Give teachers time to teach", "Cut duplicate reporting and provide high-quality lesson resources, rigorous classroom training and paid subject-conversion routes. Create senior teaching careers that reward expertise without requiring a move into administration. Support struggling staff fairly, with clear standards and due process where performance remains inadequate."),
             ("Safe, focused classrooms", "Set clear behavior expectations and phone-free instructional time, with accessible exceptions for health and disability. Provide early help for repeated disruption and alternative provision when necessary. Publish attendance and safety results without using crude league tables that punish schools for serving harder circumstances."),
             ("Support the whole learner", "Give children with additional needs one coordinator and a legally time-limited support plan. Preserve regional-language teaching where communities use it alongside national-language proficiency. School meals, transport and disability support will be coordinated so practical hardship does not become an obstacle to learning."),
             ("Prepare for adult decisions", "Teach contracts, compound interest, tax, media verification, constitutional rights and responsible technology use. Independent qualification standards will make academic, technical and apprenticeship routes intelligible to families and employers. Every provider will publish destinations and completion, with context and protection for small groups."),
         ], delivery="By 2069: the core standards and additional-needs timetable. Annual school and destination reporting thereafter."),
    dict(id="science", part=0, title="Turn knowledge into opportunity.",
         intro="An outward-looking country needs excellent universities and respected technical routes. Discovery should enrich national life and make Caprica a place where new industries choose to grow.",
         entries=[
             ("Build technical excellence", "Agree regional college programs with employers in construction, maritime engineering, health, energy, advanced manufacturing and cyber security. Fund equipment and placements through published agreements. Qualifications will be portable, and employers will help evaluate whether graduates can do the work the course promises."),
             ("Tell students the full story", "Before enrollment, publish course completion, teaching intensity, employment, earnings ranges and likely debt. Distinguish educational value from a guaranteed salary. Comparable information and accessible advice should help school leavers and mature students choose between university, technical training and apprenticeships."),
             ("Protect free inquiry", "Preserve university autonomy, peer review and academic freedom. Civil restrictions on research require a specific security or safety justification, independent scrutiny and an appeal route. Stable competitive grants will support fundamental research alongside applied work; discoveries cannot all be ordered to a political timetable."),
             ("Help discoveries become firms", "Use standard licensing terms, time-limited proof-of-concept awards and researcher enterprise leave to reduce negotiation delays. Public support will disclose ownership and return arrangements. Each program will publish its additional private investment, commercialization outcomes and failures rather than count press releases as progress."),
             ("Welcome talent and bring it home", "Offer efficient research visas, Columbian mobility and competitive return fellowships for Caprican scientists abroad. Verify qualifications and apply proportionate screening in sensitive fields. Housing, laboratory access and professional recognition must be planned alongside recruitment so institutions can make credible offers."),
             ("Connect science with national needs", "Run open research challenges in resilient agriculture, clean power, medicines, maritime systems and secure computing. SMEs and universities may form consortia. Test commercial demand and public value before scaling support, with sunset dates and independent evaluation built into every award."),
         ], delivery="By 2070: standard research licenses, regional technical compacts and a public research-to-industry results register."),
    dict(id="gateway", part=0, title="A gateway that creates opportunity.",
         intro="At the Twin Strait, between Columbia and the wider world, Caprica can turn its geography into better jobs and stronger businesses. The benefit must reach beyond the port gate.",
         entries=[
             ("Join the links into one plan", "Publish a national development pipeline connecting ports, freight routes, clean power, water, housing and skills. Rank projects by tested demand and economic value. A port expansion without a reliable road, workforce or electricity connection will not count as a complete investment case."),
             ("Make trade simpler", "Create a single digital customs window and trusted-trader corridors with Columbian partners. Use risk-based inspections and publish clearance times, appeals and service standards. Food, safety and biosecurity checks remain credible while routine exporters avoid submitting the same verified documents to multiple agencies."),
             ("Welcome investment with clear rules", "Offer investors a published timetable, one accountable coordinator and predictable commercial law. Review control of critical ports, defense, energy, telecoms and sensitive data through a narrow, time-limited screening process. Ordinary investment should receive an answer without political bargaining or hidden conditions."),
             ("Let smaller exporters participate", "Provide shared certification advice, trade finance on commercial terms and help with digital sales, language and logistics. Publish fees and eligibility. Export support will be evaluated by additional sales and repayment, with exposure limits and loss reporting rather than unlimited government guarantees."),
             ("Grow complete industries", "Support competitive clusters in maritime services, clean technology, food processing, research and digital trade. Link training and infrastructure to genuine private demand. Firms must compete for contracts and customers; government will fund enabling capacity without guaranteeing the survival of individual commercial champions."),
             ("Share the gains locally", "Require major publicly supported projects to publish apprenticeship opportunities, supplier tenders, local infrastructure costs and community benefits. Housing and service capacity must expand with new employment. A national gateway succeeds when nearby households can afford to live there and regional producers can use it."),
         ], delivery="First year: a ranked development pipeline, customs service standards and transparent investment screening deadlines."),
    dict(id="regions", part=0, title="Build a future close to home.",
         intro="A farming family, an island exporter and a town trying to keep its young people need connections that work. National development will draw on the strengths of every region.",
         entries=[
             ("Keep more value on the farm", "Co-invest in precision fertilizer, smart irrigation, soil monitoring and safe processing equipment through time-limited accounts. Pay against verified adoption and measurable benefits. Local food processing and cold-chain capacity will help producers capture more value before goods leave their region."),
             ("Protect water and natural assets", "Publish water quality and repair schedules for rural systems, with transparent priority for health risks. Use stewardship payments, conservation easements and independently assessed habitat credits. Protect major forests and sensitive coasts while allowing well-managed tourism and productive use under clear standards."),
             ("Give small ports useful connections", "Test upgrades to rural freight corridors and inter-island ferries against reliable service, safety and economic value. Tender essential routes transparently. Discount genuinely spare off-peak capacity where it helps small producers without crowding out normal freight or creating an open-ended subsidy."),
             ("Treat broadband as basic infrastructure", "Map coverage gaps, publish minimum service performance and tender support only where the market will not deliver. Require open wholesale access where public money funds networks. Clinics, schools, farms and small firms need usable connections, including backup arrangements during storms."),
             ("Keep fisheries productive", "Set multiyear catch limits from independent stock assessments, with transparent allocation and fair access for small operators. Strengthen vessel monitoring, landing traceability and biosecurity. Open safe field trials for resilient crops and gene editing under independent assessment rather than blanket permission or prohibition."),
             ("Give regions room to deliver", "Agree multiyear transport, skills and water budgets with measurable service outcomes. Local leaders choose practical delivery within national rights, safety and fiscal rules. Publish regional results so communities can see whether the promised investment, jobs and services actually arrived."),
         ], delivery="By 2069: regional growth compacts, rural water priorities and a published broadband gap-and-repair map."),
    dict(id="fiscal-rules", part=1, title="Rules that protect tomorrow.",
         intro="Debt at 69% of GDP is progress. Discipline now means preserving the services and investment people depend on while rebuilding room to respond to the next shock.",
         entries=[
             ("A lower debt goal for 2072", "Aim to reduce gross debt from 69% of GDP in 2068 to 65% by 2072 under normal economic conditions. Keep the separate statutory net-debt ceiling below 70%. Publish both measures and contingent liabilities; gross and net debt are not interchangeable."),
             ("A successor spending rule", "Continue normal-times restraint on current spending after the old 70% threshold has been passed: a default ceiling of CPI plus population growth. Any allowance for independently assessed aging, health or other service pressures needs published funding and an explicit parliamentary vote."),
             ("Fund lasting promises with lasting revenue", "Match recurring commitments to recurring revenue or verified permanent savings. Do not finance permanent tax cuts with asset sales, temporary windfalls or hoped-for growth. Preserve sovereign-wealth principal and publish withdrawals, investment income and obligations separately so the balance sheet stays intelligible."),
             ("Test investment before releasing money", "Projects above 1 billion aurums require an options appraisal, reference design, quantified cost and benefit ranges, delivery authority and funded maintenance. Smaller projects face proportionate scrutiny. Independent gateway reviews will release money in stages, with cost overruns and guarantees visible to Parliament."),
             ("Correct misses openly", "If a budget departs from the certified debt path, Treasury must publish a correction plan within 30 days, including distributional and growth effects. Parliament will decide its pace. Avoid automatic cuts that deepen a downturn, and explain which commitments are delayed, redesigned or funded differently."),
             ("Keep an emergency escape clause", "A serious recession, disaster or security emergency may justify a temporary departure, with lawful activation, a quantified ceiling and quarterly reporting. Automatic stabilizers remain outside the ordinary spending ceiling. Any departure needs renewal after 12 months and a realistic return plan."),
         ], delivery="First budget: the 2068-2072 fiscal framework, independent stress tests and a transparent capital pipeline."),
    dict(id="funding", part=1, title="Make the funding part of the promise.",
         intro="A manifesto should explain who pays, when a commitment starts and what changes if the money is not there. These are funding routes and decision rules, not invented certified costings.",
         entries=[
             ("Tax and household support", "Prioritize statutory indexation, the earnings credit and essential caring support within the current-spending envelope. Cost new housing savings relief and shared equity before allocation. Further rate cuts proceed only after independent assessment confirms a funded route to the 2072 debt goal."),
             ("Homes and networks", "Use published development levies, station-area value capture and competitively tendered public land to fund growth-related capacity. Apply borrowing to independently tested capital projects with repayment plans. Disclose land-price sensitivity and do not spend the same expected receipt on more than one promise."),
             ("Skills and childcare", "Redirect genuinely unused training-levy balances and consolidate overlapping grants into accredited places and portable accounts. Protect service access during the transition. Savings count only after contracts, administration costs and replacement capacity are verified, with published distribution across regions and family circumstances."),
             ("Health and care", "Shift commissioning toward primary, community and timely elective care within a published multiyear envelope. Expand staff and treatment capacity before assuming fewer hospital admissions. Do not count projected prevention benefits as cash available today, or close existing provision before replacement services are working."),
             ("Clean power and resilience", "Return at least half of emissions-auction receipts to households. The remaining receipts may fund grid resilience and time-limited transition investment, with reserves for volatility. Competitive energy contracts disclose long-term consumer costs; auction money will not underwrite permanent public-sector payroll."),
             ("Defense and administration", "Reallocate verified savings from excess military estate, duplicated procurement and administration toward sea, air and reserve readiness. Publish the transition costs first. Digital efficiencies must be audited after delivery, and neither defense guarantees nor public-private liabilities may sit outside the fiscal accounts."),
         ], delivery="Before each budget vote: publish ten-year costs, assumptions, service effects and an independent affordability assessment."),
    dict(id="health", part=1, title="Care you can count on.",
         intro="When someone you love is ill, a promise without a timetable is little comfort. Universal coverage must come with timely care, clinical quality and a clear route through the system.",
         entries=[
             ("Primary care with a clock", "Set same-day access for urgent primary-care needs and a seven-day routine appointment standard, phased against verified workforce capacity. Expand multidisciplinary clinics and safe pharmacist and nurse-practitioner roles. Report actual waits by district, including those unable to book, rather than only completed appointments."),
             ("A route around excessive waits", "If an accredited public service misses a clinically defined maximum elective wait, the commissioning authority must arrange another suitable provider at no extra patient charge. Apply identical quality and reporting rules. Publish capacity and referral agreements before the guarantee takes effect."),
             ("Mental health without a maze", "Use one triage pathway, community crisis teams and a named navigator. Guarantee first clinical contact within 14 days for urgent non-emergency under-25 referrals by 2070; emergency cases require immediate assessment. Publish subsequent treatment waits so first contact does not become an empty administrative milestone."),
             ("Find serious illness earlier", "Coordinate cancer screening, diagnostic referral and treatment with published regional timelines. Invest in evidence-backed precision diagnostics, rehabilitation and speech therapy. Protect access for people outside major cities through transport support, outreach and clinically appropriate remote care rather than a digital-only system."),
             ("Let the record follow the patient", "Build an interoperable, patient-accessible record with permission controls, access logs and correction rights. Emergency access must be justified and audited. Continuity across hospital, primary care and community services should reduce repeat histories and errors without opening private health information to routine browsing."),
             ("Judge providers by results", "Require common definitions for mortality, infection, safety incidents and patient experience across public and independent providers. An independent inspector will conduct unannounced visits and enforce improvement plans. Commission quality and continuity, with safeguards against avoiding patients whose needs are complex or costly."),
         ], delivery="2069: funded district access plans. By 2070: the youth first-contact standard and published treatment-wait reporting."),
    dict(id="families", part=1, title="Security through every stage of life.",
         intro="A good life includes raising a child, living independently with a disability, caring for a parent and retiring with dignity. The system should respect these responsibilities and choices.",
         entries=[
             ("Support families fairly", "Keep refundable family and childcare support neutral between family structures. Offer monthly payment and extended-hour care options under common accreditation. Publish take-up and out-of-pocket costs, so help reaches shift workers, single parents and families outside major cities as well as conventional office-hour households."),
             ("Stand behind unpaid caregivers", "Maintain the caregiver credit and pension contribution protection during intensive caring periods. Introduce a funded minimum respite offer with local flexibility, practical training and a named coordinator. Explain eligibility and appeal rights in plain language, and phase expansion against staff and provider capacity."),
             ("Make independent living practical", "Combine accessible-home adaptations, community transport and coordinated health and support assessments. Offer workplace adaptation vouchers and supported employment with measured outcomes. Disability support must follow assessed need; trying work or education should not mean risking an abrupt loss of essential care."),
             ("Protect retirement confidence", "Honor accrued pension rights and publish long-term pension sustainability assessments. Any prospective reform needs clear notice, transition protection and independent costing. Prioritize predictable basic support and accessible care; avoid promising an unfunded universal increase that tomorrow's workers must pay for."),
             ("Let older people choose", "Support safe aging at home with falls prevention, primary care and home adaptations, alongside properly inspected residential options. Expand accessible smaller homes near shops and family. Maintain telephone and face-to-face public services so no one must master a new app to receive an entitlement."),
             ("A dependable safety net", "Provide a single explanation of working-age entitlements, clear earnings disregards and a gradual taper. Human review must precede adverse fraud or error decisions, with repayment terms that consider hardship. Enforce deliberate organized fraud while protecting lawful claims and a meaningful right of appeal."),
         ], delivery="First year: publish the care and pension baseline. By 2070: coordinated assessments and the funded respite offer."),
    dict(id="energy", part=1, title="Reliable power. A lasting climate settlement.",
         intro="A household needs manageable bills. A factory needs dependable power. Caprica's net-zero position should support both while building industries that can compete around the world.",
         entries=[
             ("Keep the cap and share the return", "Maintain a binding emissions cap with predictable auctions and return at least half of receipts to households on an equal, transparent basis. Publish allowance prices, emissions and distributions. Dividend amounts will reflect actual revenue; government will not promise a fixed payment from a variable source."),
             ("Buy dependable clean capacity", "Run technology-neutral auctions that distinguish energy from dependable capacity. Storage, demand response, geothermal, advanced nuclear and other firm low-carbon options must compete on cost, reliability and verified emissions. Contracts will disclose consumer obligations, performance penalties and the cost of backup."),
             ("Connect projects ready to build", "Replace speculative grid queues with transparent first-ready, first-served rules and standard offers. Reinforce networks around new homes, ports and industrial demand. Publish connection dates and charges, with independent appeals and safeguards against passing poorly justified project costs to ordinary bill payers."),
             ("Keep nuclear decisions rigorous", "Require independent regulation, site screening and a funded waste and decommissioning plan before any small modular reactor procurement. Evaluate alternatives on whole-life cost, safety and reliability. Public guarantees and cancellation liabilities must be disclosed and fit within the national fiscal framework."),
             ("Give households useful choices", "Offer voluntary time-of-use tariffs, clear comparison tools and targeted efficiency finance backed by verified savings. Protect vulnerable consumers during installation or disputes. Communities hosting major infrastructure will receive transparent benefits, while national consent rules protect necessary projects and environmental standards."),
             ("Grow clean industry responsibly", "Award competitive, time-limited commercialization grants for exportable clean technologies and repair or recycling systems. Publish additional investment, verified emissions effects and jobs. End support that fails agreed tests, and protect forests, waterways and coastlines through measurable conservation and adaptation standards."),
         ], delivery="By 2069: transparent auctions and connection dates. Quarterly reporting on bills, reliability, emissions and dividends."),
    dict(id="networks", part=1, title="Make everyday connections dependable.",
         intro="A missed bus, unsafe water or a weak mobile signal can determine whether a job or appointment is possible. Maintenance and reliable service are national development in daily life.",
         entries=[
             ("One journey, one fare cap", "Introduce an interoperable payment account and automatic best-price weekly cap across participating rail, bus and ferry networks. Retain cash or assisted options and a clear apprentice fare. Agree operator revenue sharing before rollout so integrated fares do not quietly remove service from less profitable routes."),
             ("Build rail where it works", "Evaluate regional upgrades, including the southern high-speed corridor, against passenger demand, journey time, cost and alternatives. Coordinate local buses and feeder rail with major stations. Publish staged business cases and operating subsidies, with independent reviews before each major construction commitment."),
             ("Fix what already exists", "Set a published maintenance floor within transport and water capital budgets. Map asset condition, safety risks and deferred maintenance. Prioritize bridges, junctions, pipes and drainage by public value, giving reliable upkeep the same scrutiny and visibility as a new megaproject."),
             ("Clean water with an accountable owner", "Require utilities to publish test results, leakage and repair schedules by service area. Independent regulation will set quality and investment obligations across ownership models. Emergency repairs take priority; long-term contracts must disclose financing costs, failure penalties and responsibility for replacement assets."),
             ("Digital service everywhere", "Use competitive gap-funding tenders and open wholesale access for underserved areas. Publish real speed, reliability and restoration results. Critical clinics, schools and public services require backup connections; consumers need easy switching and compensation when providers repeatedly miss their contractual standards."),
             ("Publish the true project price", "Use standard contracts, open-book variation rules and independent dispute resolution. Show capital, operating, maintenance and financing costs together. A major-projects unit will monitor delivery, but sponsoring ministers and named authorities remain accountable for decisions and overruns."),
         ], delivery="By 2070: interoperable fare agreements and public network-condition reporting, with regional rollout milestones."),
    dict(id="justice", part=1, title="Safe streets. Fair and effective justice.",
         intro="Freedom is fragile when intimidation controls a street or justice takes years. Government must protect the public with visible policing, capable courts and rules that command trust.",
         entries=[
             ("Put policing where people need it", "Build on national policing standards with visible neighborhood teams, specialist organized-crime units and modern forensics. Reduce duplicate administration and publish staffing, response times and complaints. Independent oversight and consistent training will help officers earn the confidence of the communities they serve."),
             ("Break criminal networks", "Target money laundering, trafficking and gang logistics through coordinated investigators and prosecutors. Courts may order disclosure of the lawful origin of assets linked to serious crime, with legal assistance and appeal. Seizure powers must follow evidence, not an assumption that wealth itself proves wrongdoing."),
             ("Move cases without cutting corners", "Expand court capacity and digital case management, with priority for repeat violence and vulnerable victims. Publish delays and adjournment causes. Preserve disclosure, representation and the presumption of innocence; faster justice must come from better capacity and administration rather than weaker defense rights."),
             ("Give victims a clear voice", "Provide regular case updates, trauma support, a national witness-protection service and statutory compensation decision periods. A victims' code will set responsibilities and complaint routes. Survivors should not have to repeat their story to every agency or navigate protection alone."),
             ("Prevent repeat harm", "Combine early family support, school attendance interventions and mentoring with proportionate consequences for serious repeat offending. Control gang leadership and illicit communications in prisons, while expanding rehabilitation and education. Judge programs by repeat offending and safety, not the number of people processed."),
             ("Keep power tied to evidence", "Allow specific, judicially authorized evidence gathering without a general encryption backdoor. Risk tools may assist resource allocation but cannot establish suspicion, guilt or detention. Consequential uses must be disclosed and contestable, with human responsibility and independent review."),
         ], delivery="Annual justice plan: staffing, court capacity, victim support and public reporting under independent oversight."),
    dict(id="defense", part=1, title="An island nation, ready to defend itself.",
         intro="Our prosperity crosses the sea. A credible force must protect Caprica's approaches, keep commerce moving and meet defined Columbian commitments, with equipment and people ready for the mission.",
         entries=[
             ("Make the navy the senior service", "Prioritize submarines, escorts, patrol vessels, unmanned maritime systems and coastal missiles within a funded capability plan. Protect sea lanes and port approaches through layered surveillance and denial. Procurement will include crews, ammunition, maintenance and infrastructure rather than count hulls that cannot deploy."),
             ("Strengthen the air picture", "Invest in maritime patrol, airborne early warning, fighters, tankers, strategic lift and resilient air defense. Disperse and harden operating bases and protect communications. Choose interoperable systems through competitive evaluation, with spare parts and training included in the lifetime cost."),
             ("A smaller, more capable army", "Shift from mass formations toward mobile brigades, coastal defense, engineering, special operations and Columbian reinforcement. Integrate drones and protected communications down to small units. Protect training quality and personnel support during restructuring, with transition costs and capability gaps explained to Parliament."),
             ("Strengthen reserves and logistics", "Expand trained reserves, specialist civilian skills and stockpiles against independently tested scenarios. Exercise mobilization and reinforcement with partners. Pre-agree access to merchant shipping and critical logistics, with lawful compensation and clear command arrangements during a national emergency."),
             ("Buy readiness and sustainment", "Publish a ten-year funded capability plan and quarterly public readiness summaries, with classified scrutiny where necessary. Open procurement to competition and build credible domestic maintenance capacity. Reallocate verified savings from excess estate and overhead, without assuming every future efficiency is already money in the bank."),
             ("Set limits on military missions", "Force requires lawful authority, defined achievable aims and a credible exit. Seek parliamentary approval for deployments beyond immediate defense, with prompt review of emergency action. Meet treaty commitments while rejecting open-ended wars intended to remake another country's political system."),
         ], delivery="First year: a costed sea-and-air capability plan. By 2072: independently tested readiness against assigned missions."),
    dict(id="resilience", part=1, title="A country that keeps going.",
         intro="Confidence means knowing the hospital, water system and government can function through a storm, cyberattack or supply interruption. Preparedness protects ordinary life as well as national security.",
         entries=[
             ("Know the weak links", "Maintain a national register of critical infrastructure ownership, dependencies, service minima and recovery targets. Publish a useful public summary and secure operational details. Regulators will test whether one supplier, cable or power failure could disable several essential services at once."),
             ("Plan for 30 days of disruption", "Require hospitals, water, telecoms, major ports and public data centers to maintain tested continuity plans for prolonged external supply interruption. Standards will cover backup power, consumables, staffing and alternate routes. Demonstrated capability, not an untested stockpile inventory, will determine compliance."),
             ("Train a civil reserve", "Create voluntary trained medical, engineering, communications and logistics units that can support local authorities and Columbian disaster response. Set insurance, employment protection and deployment terms clearly. Regular exercises will bring public services, community organizations and private operators together before a crisis."),
             ("Warn people in time", "Test cell broadcast, radio fallback and multilingual accessible alerts twice a year. Publish evacuation and shelter arrangements, including transport for people with disabilities or care needs. Local hubs will connect backup power, trusted information and practical support when ordinary networks fail."),
             ("Protect essential supplies", "Map exposure in medicines, fuel, food, transformers, semiconductors and defense components. Use diverse suppliers, rotating reserves and reciprocal agreements where they offer value. Review the cost of resilience against the damage of disruption, avoiding wasteful stockpiles of items that cannot be maintained or used."),
             ("Adapt to local risks", "Co-fund flood, coastal, heat and earthquake resilience through independently assessed regional plans. Use land-use rules, natural defenses and targeted engineering together. Publish who is responsible for maintenance and explain residual risks rather than imply that any project can make every community invulnerable."),
         ], delivery="By 2070: tested critical-service continuity plans and public regional resilience scorecards."),
    dict(id="rights", part=2, title="Your rights are part of the foundation.",
         intro="A strong country trusts free people. Rights should be clear enough to use, strong enough to enforce and equal for everyone, whatever their background, beliefs or lawful choices.",
         entries=[
             ("Protect expression and conscience", "Strengthen the Bill of Rights protection for political, academic, artistic and religious expression, including the freedom not to believe. Enforce laws against direct threats, harassment and incitement under precise tests. Peaceful disagreement and criticism of government must remain lawful and protected."),
             ("Equal citizenship under law", "Defend equal treatment, existing marriage rights and protection against unlawful discrimination. Public institutions must serve people fairly, without arbitrary group preferences or penalties for lawful identity or belief. Reasonable accommodation must not deny someone else equal access to an essential public service."),
             ("Make privacy enforceable", "Require a specific lawful purpose, proportionate collection and clear retention periods for personal data. Provide access, correction and deletion where retention is no longer justified. An independent commissioner must be able to investigate, order remedies and penalize serious misuse by government or private operators."),
             ("Put warrants before intrusion", "Intrusive surveillance requires judicial authorization, with rapid review of genuine emergency use. Support the Nuremberg Act framework for lawful intelligence while requiring necessity, proportionality and an audit trail. Agencies may not target journalism, peaceful association or political belief merely because it is inconvenient."),
             ("End exceptional powers on time", "Emergency powers will have automatic sunsets, prompt parliamentary scrutiny and renewal only on a published case. Release reasons and records when operational sensitivity permits. Courts and independent oversight remain available, including during a crisis, so temporary necessity does not become permanent convenience."),
             ("Give rights a practical remedy", "Maintain accessible complaint, legal assistance and appeal routes. Require agencies to explain adverse decisions and correct errors within a clear timetable. A right buried in a statute is insufficient if enforcing it takes unaffordable years; publish resolution times and compliance with remedies."),
         ], delivery="First year: a rights and oversight review with public proposals, implementation dates and enforceable remedies."),
    dict(id="digital", part=2, title="Technology should give you more control.",
         intro="Public services can be fast without becoming intrusive. Digital tools should save time, make decisions easier to challenge and preserve a human route when a system gets something wrong.",
         entries=[
             ("One voluntary government account", "Offer a secure wallet for verified licenses, tax, benefits and business filings with separate purpose controls. Keep face-to-face, telephone and paper routes where needed. Access to essential services will not depend on a smartphone, commercial account or agreement to unrelated data use."),
             ("Tell government once, with control", "Reuse verified information only for authorized purposes, with a citizen-visible access log and a simple correction process. Limit staff access to their duties. Publish data-sharing agreements and independent audits, with effective penalties for unauthorized browsing or onward disclosure."),
             ("Keep humans accountable for AI", "Every high-impact automated public decision must have a named official, published purpose, testing record and an explanation to the affected person. Guarantee meaningful human review and a usable appeal. Test unequal error rates and disable systems that cannot meet legal and service standards."),
             ("Protect secure communications", "Reject general encryption backdoors and deliberate systemic weaknesses. Investigators can seek specific evidence under lawful, judicially supervised powers. Security research and responsible vulnerability disclosure should help protect the networks families, banks, hospitals and employers rely on."),
             ("Buy systems that can work together", "Require open standards, data portability and proportionate public source-code disclosure. Contracts must include exit plans, service continuity and ownership of public data. Independent gateway reviews will test usability and security before large deployments, with staged releases and transparent failure reporting."),
             ("Defend essential digital services", "Set common zero-trust controls, tested backups and incident-reporting duties for critical public suppliers. Carry out annual adversarial testing and maintain domestic continuity arrangements. Give smaller operators practical guidance so national standards improve security without becoming an impossible compliance hurdle."),
         ], delivery="By 2070: a public automated-decision register, meaningful human appeals and accessible alternatives in every agency."),
    dict(id="government", part=2, title="A government that answers to you.",
         intro="People should not need an inside contact to get a decision, see how money is spent or challenge misconduct. Capable institutions and limits on power belong together.",
         entries=[
             ("A decision within a known time", "Set published service clocks for permits, benefits and routine administrative applications. Name the responsible authority and provide escalation when deadlines are missed. Measure complete journeys and error correction, including assisted applications, rather than rewarding departments for moving unfinished work into another queue."),
             ("Follow public money", "Publish tenders, beneficial owners, award reasons, variations and performance in a searchable contracts register. Disclose ministerial meetings, lobbying and gifts promptly, with proportionate privacy and security exceptions. Audit the exceptions so transparency cannot be defeated by routine secrecy labels."),
             ("Investigate corruption independently", "Protect an independent anti-corruption prosecutor and watchdogs from ministerial direction. Apply the law to government, state enterprises and the military alike. Provide protected channels for lawful whistleblowing, fair investigation and due process; accusation alone must not substitute for proof."),
             ("Respect constitutional limits", "Require clear authority for executive action, effective parliamentary scrutiny and independent courts. Review electoral rules openly against equal participation, fair representation and reliable administration. Changes require public consultation and constitutional procedures, not a governing party's convenience before an election."),
             ("Put decisions close to home", "Use regional delivery agreements with multiyear budgets and national minimum standards. Publish which level of government is responsible for each service, how it is funded and where citizens can appeal. Decentralization should clarify accountability rather than let institutions blame one another."),
             ("Make the future visible", "Assess major bills for long-term effects on debt, housing, emissions and generational transfers. Strengthen freedom-of-information deadlines and public-interest tests. Publish responses to material consultation findings and citizen petitions so participation has an observable effect on decisions."),
         ], delivery="By 2069: service clocks and open registers. Quarterly manifesto reporting with independent audit and correction plans."),
    dict(id="foreign", part=2, title="Open to the world. Clear about our interests.",
         intro="Caprica can be a trusted link between nations because it is commercially open, institutionally reliable and secure. The Bluespan Doctrine joins liberal purpose with realistic judgments about power.",
         entries=[
             ("Keep the national purpose clear", "Protect citizens, territorial integrity, maritime commerce and a stable regional balance. Diplomacy, trade, science and defense will serve an agreed development strategy. Publish objectives and evaluate results so overseas activity connects to national interests and useful cooperation rather than prestige alone."),
             ("Strengthen the Columbian Union", "Meet defined treaty obligations and deepen practical cooperation on maritime surveillance, disaster response, logistics and infrastructure standards. Maintain national parliamentary accountability. Joint action should address genuinely shared tasks, with regular review of functions better exercised by national or local institutions."),
             ("Complete the shared market", "Pursue mutual recognition in professional services, digital identity, procurement and product standards with enforceable competition safeguards. Coordinate energy interconnections and protection of subsea cables. Make the gains usable by small firms and mobile workers through clear rules, accessible guidance and effective dispute resolution."),
             ("Build on diplomatic progress", "Sustain normalization with OURS following the Kaoqing Communique, support Kerevan's restored territorial integrity and keep Oshmit isolated from weapons supply chains. Establish a Twin Strait crisis hotline, maritime deconfliction and incident-reporting arrangements. Continued dialogue must coexist with verification and credible deterrence."),
             ("Use force with defined limits", "Try diplomacy, targeted sanctions and coordinated pressure before military action where circumstances allow. Any use of force needs lawful authority, achievable aims and an exit strategy. Caprica will not wage open-ended wars to impose a political system, and emergency decisions remain subject to prompt parliamentary review."),
             ("Make cooperation build capacity", "Focus development partnerships on disaster resilience, health security, trade facilitation, education and accountable institutions. Publish contracts and measurable outcomes. Open scientific and student exchanges should create lasting skills and relationships, with proportionate safeguards for sensitive technology and national security."),
         ], delivery="Annual statement to Parliament: treaty readiness, market access, diplomatic objectives and results against the national strategy."),
    dict(id="trade-migration", part=2, title="An open country with dependable rules.",
         intro="Trade, investment and talent can expand the choices available to Capricans. Clear entry rules, fair competition and capable services make openness durable and trusted.",
         entries=[
             ("Diversify markets", "Pursue high-standard agreements in services, digital trade, food, clean technology and maritime commerce across Columbia, Albeuman and other partners. Publish expected gains, adjustment costs and implementation reviews. Avoid reliance on a single dominant buyer or supplier for critical economic functions."),
             ("Screen risks narrowly", "Apply defined, time-limited review to foreign control of critical infrastructure and dual-use technology. Give investors reasons and an appeal route where security permits. Coordinate responses to economic coercion with Columbian partners, with lawful, proportionate measures and clear conditions for withdrawal."),
             ("Plan migration with capacity", "Ask Parliament to set indicative annual route ranges using housing, service capacity, labor shortages and humanitarian obligations. Publish evidence and review outcomes. Recruit skills where shortages are genuine, while investing in domestic training and the infrastructure needed for communities to grow well."),
             ("Reward contribution and enforce standards", "Use verified qualifications, genuine job offers, shortage needs, language ability and appropriate sector wages in skilled entry rules. License high-risk recruiters, enforce sponsor duties and punish wage theft. Migrant workers receive equal legal protection, preventing abuse and unfair undercutting of established workers."),
             ("Make protection decisions fairly", "Target initial asylum decisions within six months, with legal support, a full merits appeal and humane reception. Enforce final refusals subject to non-refoulement and other legal duties. Counter smuggling through intelligence and international cooperation, while keeping lawful family and protection routes intelligible."),
             ("Help newcomers participate", "Provide language and civics pathways, timely qualification recognition and clear citizenship requirements for residence and serious-crime history. Make reasonable exceptions for age and disability. Integration means shared constitutional duties and equal citizenship, alongside respect for lawful cultural and religious life."),
         ], delivery="Each year: a parliamentary migration plan, market-diversification review and published route-specific processing times."),
]

EVERYDAY = [
    ("Starting out", "A first wage that goes further, a credible apprenticeship and more homes near work. Leaving school should open a choice of futures, with help that leads somewhere."),
    ("Raising a family", "Monthly childcare help, schools with strong foundations and public services with a clear timetable. Parents should be able to plan the week and the years ahead."),
    ("Building a business", "Predictable taxes, a quick route to incorporation and public invoices paid on time. The same open rules should serve the independent shop and the ambitious exporter."),
    ("Working and changing careers", "Portable training, fair workplace rules and support that tapers as earnings rise. Experience should remain an asset when an industry changes or a caring break ends."),
    ("Caring and growing older", "Respite, accessible healthcare, protected accrued pension rights and a human route through public services. Independence and dignity belong to every stage of life."),
    ("Putting down regional roots", "Clean water, rural broadband, useful freight routes and local training. A young person should be able to see opportunity in the community that raised them."),
]

